// zoneBase is the generated base of table zone. It holds the table (t),
// typed predicates (where), helpers that run in the context transaction and
// return the model rows, and the pkg/db/transactor functions as methods.
// Embed it in the implementation and set it with newZoneBase(db).
type zoneBase struct {
	db    qrm.DB
	t     *table.ZoneTable
	where zoneWhere
}

// newZoneBase returns the base of table zone. It runs its statements on the
// transaction of the context, and on db outside one.
func newZoneBase(db qrm.DB) zoneBase {
	return zoneBase{db: db, t: table.Zone}
}

// findOne returns the row matching cond: absent when none does, and
// transactor.ErrMoreThanOneRow when two do. It reads LIMIT 2, so a key that
// stopped being unique is an error, never a silent first row. To pick one of
// several rows, use first with an order.
func (b zoneBase) findOne(ctx context.Context, cond postgres.BoolExpression) (functional.Option[model.Zone], error) {
	stmt := b.t.SELECT(b.t.AllColumns)
	if cond != nil {
		stmt = stmt.WHERE(cond)
	}
	rows, err := b.queryRows(ctx, stmt.LIMIT(2)).Value()
	switch {
	case err != nil:
		return functional.None[model.Zone](), err
	case len(rows) > 1:
		return functional.None[model.Zone](), fmt.Errorf("%w: zone", transactor.ErrMoreThanOneRow)
	case len(rows) == 0:
		return functional.None[model.Zone](), nil
	}
	return functional.Some(rows[0]), nil
}

// first returns the first row matching cond in the given order, absent when
// none does. End the order with a unique column, such as the primary key, so
// the row it picks is stable.
func (b zoneBase) first(ctx context.Context, cond postgres.BoolExpression, order postgres.OrderByClause, more ...postgres.OrderByClause) (functional.Option[model.Zone], error) {
	stmt := b.t.SELECT(b.t.AllColumns)
	if cond != nil {
		stmt = stmt.WHERE(cond)
	}
	return b.queryRowOptional(ctx, stmt.ORDER_BY(append([]postgres.OrderByClause{order}, more...)...).LIMIT(1))
}

// findAll returns every row matching cond, every row when cond is nil, in the
// given order.
func (b zoneBase) findAll(ctx context.Context, cond postgres.BoolExpression, order ...postgres.OrderByClause) ([]model.Zone, error) {
	stmt := b.t.SELECT(b.t.AllColumns)
	if cond != nil {
		stmt = stmt.WHERE(cond)
	}
	if len(order) > 0 {
		stmt = stmt.ORDER_BY(order...)
	}
	return b.queryRows(ctx, stmt).Value()
}

